<?php
namespace App\Domain\Statistics; use App\Models\Statistic; use Illuminate\Validation\ValidationException; final class StatisticManager { public function save(array $data,?Statistic $item,int $userId):Statistic{$item??=new Statistic;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)Statistic::max('display_order')+1;}else unset($data['status']);$item->fill($data)->save();return $item;} public function publish(Statistic $item):void{$this->content($item);$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(Statistic $item,string $utc):void{$this->content($item);$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(Statistic $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(Statistic $item):void{if(app(StatisticDependencyInspector::class)->inspect($item)['blocked'])throw ValidationException::withMessages(['statistic'=>'Resolve homepage references first.']);$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(Statistic $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(Statistic $item,int $userId):Statistic{$copy=$item->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->label.=' (Verify copy)';$copy->status='draft';$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)Statistic::max('display_order')+1;$copy->save();return $copy;} public function move(Statistic $item,string $direction):void{$peer=Statistic::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}} private function content(Statistic $item):void{if(!trim($item->label)||!trim($item->value))throw ValidationException::withMessages(['statistic'=>'A truthful label and value are required.']);} }
